/**
 * Coherence's Claude Code mod installs per person from Coherence's
 * repository, which is its marketplace, and the mod's own copies of what
 * Coherence declares are generated and held equal here.
 */

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, realpathSync } from "node:fs";
import { chmod, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import { WRITERS } from "./host-tools.ts";
import { IGNORE_FILE } from "./install.ts";
import { installMod, localSettingsPath, MARKETPLACE_FILE, MOD_FOLDER, MOD_ID, MOD_REPOSITORY, modInstalled, type ClaudeRunner } from "./mod-install.ts";
import { cli } from "./cli-fixture.ts";

const OWN_PACKAGE = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const read = (path: string): unknown => JSON.parse(readFileSync(join(OWN_PACKAGE, path), "utf8"));

/** What mods/coherence/hooks/writers.ts holds: generated from host-tools.ts. */
export const WRITERS_FILE = `// Generated from src/lifecycle/host-tools.ts (WRITERS.claude); src/lifecycle/mod-install.test.ts holds it equal. Do not edit by hand.\nexport const WRITER_TOOLS: readonly string[] = ${JSON.stringify(Object.keys(WRITERS.claude))}\n`;

test("the repository's marketplace lists the mod at the package's version, and the mod's writer tools are host-tools.ts's", () => {
  const path = join(OWN_PACKAGE, MOD_FOLDER, "hooks", "writers.ts");
  assert.equal(readFileSync(path, "utf8"), WRITERS_FILE, `${path} drifted from host-tools.ts; replace it with:\n${WRITERS_FILE}`);
  const pkg = read("package.json") as { version: string };
  const plugin = read(join(MOD_FOLDER, ".claude-plugin", "plugin.json")) as { name: string; version: string };
  const market = read(MARKETPLACE_FILE) as { name: string; plugins: { name: string; source: string }[] };
  assert.equal(plugin.version, pkg.version, "the mod and the command line it runs are one version");
  assert.equal(`${plugin.name}@${market.name}`, MOD_ID);
  assert.deepEqual(market.plugins.map((p) => [p.name, p.source]), [[plugin.name, `./${MOD_FOLDER}`]]);
});

test("install stops at the first claude plugin step that fails", () => {
  const calls: string[] = [];
  const failing: ClaudeRunner = (args) => (calls.push(args.join(" ")), { status: 1, stdout: '{"message":"no such folder"}', stderr: "" });
  const steps = installMod("/p", failing);
  assert.deepEqual(calls, [`plugin marketplace add ${MOD_REPOSITORY} --scope local --json`]);
  assert.deepEqual(steps.map((s) => [s.ok, s.said]), [[false, "no such folder"]]);
  const absent: ClaudeRunner = () => ({ status: null, stdout: "", stderr: "spawn claude ENOENT" });
  assert.match(installMod("/p", absent)[0]!.said, /claude could not be run \(spawn claude ENOENT\)/);
});

/** A `claude` on the PATH that writes the personal settings as Claude Code's plugin commands do, and logs each call. */
const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs");
const args = process.argv.slice(2);
fs.appendFileSync(process.env.FAKE_CLAUDE_LOG, args.join(" ") + "\\n");
const file = args.includes("project") ? ".claude/settings.json" : ".claude/settings.local.json";
let s = {};
try { s = JSON.parse(fs.readFileSync(file, "utf8")); } catch {}
const verb = args.slice(0, args[1] === "marketplace" ? 3 : 2).join(" ");
if (verb === "plugin marketplace add") s.extraKnownMarketplaces = { other: { source: { source: "github", repo: "o/r" } }, coherence: { source: { source: "github", repo: args[3] } } };
else if (verb === "plugin install") s.enabledPlugins = { ...s.enabledPlugins, [args[2]]: true };
else if (verb === "plugin uninstall") delete (s.enabledPlugins ?? {})[args[2]];
fs.mkdirSync(".claude", { recursive: true });
fs.writeFileSync(file, JSON.stringify(s, null, 2) + "\\n");
console.log(JSON.stringify({ outcome: "ok", message: "done: " + verb }));
`;

test("hooks install --mod installs the mod at the personal scope from Coherence's repository, hands it the personal hooks, keeps the team's and names them, and uninstall takes out the mod and its declaration alone", async () => {
  const project = await mkdtemp(join(tmpdir(), "coherence-mod-install-"));
  try {
    assert.equal(spawnSync("git", ["init", "-q"], { cwd: project }).status, 0);
    const bin = join(project, "bin");
    await mkdir(bin);
    await writeFile(join(bin, "claude"), FAKE_CLAUDE);
    await chmod(join(bin, "claude"), 0o755);
    const log = join(project, "claude.log");
    const env = { ...process.env, PATH: `${bin}:${process.env["PATH"]}`, FAKE_CLAUDE_LOG: log };
    const hooks = (...args: string[]) => cli(["hooks", ...args], { cwd: project, env });

    assert.equal((await hooks("install", "--host", "claude")).status, 0, "the team's committed hooks");
    assert.equal((await hooks("install", "--host", "claude", "--local")).status, 0, "and this person's");
    assert.equal((await hooks("install", "--host", "codex", "--mod")).status, 64, "the mod is Claude Code's alone");
    assert.equal((await hooks("install", "--host", "claude", "--mod", "--local")).status, 64, "the mod is always personal");

    const installed = await hooks("install", "--host", "claude", "--mod");
    assert.equal(installed.status, 0, installed.stderr);
    assert.deepEqual(readFileSync(log, "utf8").trim().split("\n"), [`plugin marketplace add ${MOD_REPOSITORY} --scope local --json`, `plugin install ${MOD_ID} --scope local --json`]);
    const local = JSON.parse(await readFile(join(project, ".claude", "settings.local.json"), "utf8")) as Record<string, unknown>;
    assert.equal(local["hooks"], undefined, "the personal settings hooks leave: the mod would stand aside for each");
    assert.equal(modInstalled(project), true);
    assert.match(installed.stdout, /settings\.json still runs Coherence for SessionStart.*the mod answers none of those events while it does/, "the team's hooks are kept and named");
    assert.match((await hooks("--check", "--host", "claude", "--local")).stdout, new RegExp(`${MOD_ID} is enabled in the personal settings and answers every event`));
    assert.match((await hooks("status")).stdout, new RegExp(`${MOD_ID} enabled in the personal settings`));

    // The committed hooks leave; .coherence's own files stay while the mod still runs Coherence.
    await writeFile(log, "");
    assert.equal((await hooks("uninstall", "--host", "claude")).status, 0);
    assert.deepEqual(readFileSync(log, "utf8").trim().split("\n"), [`plugin uninstall ${MOD_ID} --scope local --json`], "the mod leaves first, and the marketplace is never removed: that would uninstall the mod from every project on the machine");
    assert.equal(modInstalled(project), false);
    const after = JSON.parse(await readFile(join(project, ".claude", "settings.local.json"), "utf8")) as { extraKnownMarketplaces?: Record<string, unknown> };
    assert.deepEqual(Object.keys(after.extraKnownMarketplaces ?? {}), ["other"], "only the declaration install wrote leaves");
    assert.equal(existsSync(join(project, IGNORE_FILE)), false, "with nothing left running Coherence, the ignore file goes as before");

    // Claude Code's local scope in a git worktree is the main checkout's file: the mod is read, and its declaration dropped, there.
    const git = (...args: string[]) => assert.equal(spawnSync("git", ["-c", "user.email=t@example.com", "-c", "user.name=t", ...args], { cwd: project }).status, 0, args.join(" "));
    git("commit", "-q", "--allow-empty", "-m", "start");
    const tree = join(project, "tree");
    git("worktree", "add", "-q", tree);
    assert.equal(localSettingsPath(tree), join(realpathSync(project), ".claude", "settings.local.json"));
    await writeFile(join(project, ".claude", "settings.local.json"), JSON.stringify({ enabledPlugins: { [MOD_ID]: true } }));
    assert.equal(modInstalled(tree), true, "enabled in the main checkout is enabled in its worktree");
  } finally {
    await rm(project, { recursive: true, force: true });
  }
});

test("while the mod is the only thing running Coherence, removing the last settings hook keeps .coherence's own files", async () => {
  const project = await mkdtemp(join(tmpdir(), "coherence-mod-keeps-"));
  try {
    assert.equal(spawnSync("git", ["init", "-q"], { cwd: project }).status, 0);
    assert.equal((await cli(["hooks", "install", "--host", "claude"], { cwd: project })).status, 0);
    await writeFile(join(project, ".claude", "settings.local.json"), JSON.stringify({ enabledPlugins: { [MOD_ID]: true } }));
    const { uninstall } = await import("./install.ts");
    const result = await uninstall(project, "claude");
    assert.equal(result.removedIgnore, false);
    assert.ok(existsSync(join(project, IGNORE_FILE)));
  } finally {
    await rm(project, { recursive: true, force: true });
  }
});

test("hooks install --mod --shared enables the mod in the committed settings in place of the committed Claude Code hooks, keeps the other host's, and uninstall takes it out", async () => {
  const project = await mkdtemp(join(tmpdir(), "coherence-mod-shared-"));
  try {
    assert.equal(spawnSync("git", ["init", "-q"], { cwd: project }).status, 0);
    const bin = join(project, "bin");
    await mkdir(bin);
    await writeFile(join(bin, "claude"), FAKE_CLAUDE);
    await chmod(join(bin, "claude"), 0o755);
    const log = join(project, "claude.log");
    const env = { ...process.env, PATH: `${bin}:${process.env["PATH"]}`, FAKE_CLAUDE_LOG: log };
    const hooks = (...args: string[]) => cli(["hooks", ...args], { cwd: project, env });

    assert.equal((await hooks("install", "--host", "claude")).status, 0);
    assert.equal((await hooks("install", "--host", "codex")).status, 0);
    assert.equal((await hooks("install", "--host", "claude", "--shared")).status, 64, "--shared belongs to --mod");
    const installed = await hooks("install", "--host", "claude", "--mod", "--shared");
    assert.equal(installed.status, 0, installed.stderr);
    assert.deepEqual(readFileSync(log, "utf8").trim().split("\n"), [`plugin marketplace add ${MOD_REPOSITORY} --scope project --json`, `plugin install ${MOD_ID} --scope project --json`]);
    const committed = JSON.parse(await readFile(join(project, ".claude", "settings.json"), "utf8")) as Record<string, unknown>;
    assert.equal(committed["hooks"], undefined, "the committed Claude Code hooks leave: the mod would stand aside for each");
    assert.equal(modInstalled(project, "project"), true);
    assert.ok(existsSync(join(project, ".codex", "hooks.json")) && readFileSync(join(project, ".codex", "hooks.json"), "utf8").includes("hook Stop"), "Codex keeps its hooks");
    assert.ok(existsSync(join(project, IGNORE_FILE)), ".coherence's own files stay");
    const check = await hooks("--check", "--host", "claude");
    assert.equal(check.status, 0, check.stdout);
    assert.match(check.stdout, new RegExp(`${MOD_ID} is enabled in the committed settings and answers every event`));
    assert.match((await hooks("status")).stdout, new RegExp(`${MOD_ID} enabled in the committed settings`));

    await writeFile(log, "");
    assert.equal((await hooks("uninstall", "--host", "claude")).status, 0);
    assert.deepEqual(readFileSync(log, "utf8").trim().split("\n"), [`plugin uninstall ${MOD_ID} --scope project --json`]);
    assert.equal(modInstalled(project, "project"), false);
    const after = JSON.parse(await readFile(join(project, ".claude", "settings.json"), "utf8")) as { extraKnownMarketplaces?: Record<string, unknown> };
    assert.deepEqual(Object.keys(after.extraKnownMarketplaces ?? {}), ["other"], "only the declaration install wrote leaves");
  } finally {
    await rm(project, { recursive: true, force: true });
  }
});

/**
 * Where the language servers and the tsserver are found: by Node's package
 * resolver, from the project, then from Coherence's own module, then PATH,
 * over fake installs laid out the way npm and pnpm lay them out. Under pnpm
 * Coherence's dependencies sit beside its package in the store, not inside
 * it, and TypeScript 7 ships no tsserver: an adopter on pnpm and
 * TypeScript 7 could not start the TypeScript instrument at all (df-aa4a8606).
 */

import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readdirSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { after, test } from "node:test";
import { fileURLToPath } from "node:url";
import { installedPackage, locateServer, locateTsserver, tsserverNotice } from "./installed.ts";
import { startContext, tsserverBlock } from "../lifecycle/hook.ts";

// The real path: the resolver answers with real paths, and on macOS the temporary folder is a link.
const scratch = realpathSync(mkdtempSync(join(tmpdir(), "coherence-installed-")));
after(() => rmSync(scratch, { recursive: true, force: true }));

function write(path: string, text: string): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
}

/** A package folder holding a manifest and the files named. */
function pkg(dir: string, manifest: Record<string, unknown>, files: readonly string[] = []): void {
  write(join(dir, "package.json"), JSON.stringify(manifest));
  for (const file of files) write(join(dir, file), "// fixture\n");
}

const TS7 = { name: "typescript", version: "7.0.2", type: "module", exports: { "./package.json": "./package.json", ".": "./lib/version.cjs" }, bin: { tsc: "./bin/tsc" } };
const TS7_FILES = ["lib/version.cjs", "lib/tsc.js", "bin/tsc"];
const TS5 = (version: string) => ({ name: "typescript", version, bin: { tsc: "./bin/tsc", tsserver: "./bin/tsserver" } });
const TSLS = { name: "typescript-language-server", version: "5.3.0", bin: { "typescript-language-server": "lib/cli.mjs" } };
const PYRIGHT = { name: "pyright", version: "1.1.414", bin: { pyright: "index.js", "pyright-langserver": "langserver.index.js" } };

/**
 * A pnpm project on TypeScript 7: the project's own typescript in its
 * node_modules, Coherence in the store with its own dependencies beside it,
 * none inside it. Returns the project root and the file Coherence resolves from.
 */
function pnpmProject(name: string): { root: string; coherenceFrom: string } {
  const root = join(scratch, name);
  pkg(join(root, "node_modules", "typescript"), TS7, TS7_FILES);
  const store = join(root, "node_modules", ".pnpm", "@posthog+coherence@1.5.2", "node_modules");
  const coherence = join(store, "@posthog", "coherence");
  pkg(coherence, { name: "@posthog/coherence", version: "1.5.2" }, ["dist/adapters/installed.js"]);
  pkg(join(store, "typescript"), TS5("5.9.3"), ["lib/tsserver.js"]);
  pkg(join(store, "typescript-language-server"), TSLS, ["lib/cli.mjs"]);
  pkg(join(store, "pyright"), PYRIGHT, ["index.js", "langserver.index.js"]);
  write(join(root, "package.json"), JSON.stringify({ name, devDependencies: { "@posthog/coherence": "1.5.2", typescript: "^7.0.2" } }));
  return { root, coherenceFrom: join(coherence, "dist", "adapters", "installed.js") };
}

test("under pnpm with TypeScript 7, the tsserver and both language servers are Coherence's own, resolved beside its package, and the project's TypeScript is named as passed over", () => {
  const { root, coherenceFrom } = pnpmProject("pnpm-ts7");
  const store = join(root, "node_modules", ".pnpm", "@posthog+coherence@1.5.2", "node_modules");
  // The project's resolver cannot reach lib/tsserver.js: TypeScript 7's exports refuse the subpath, and the file is not there.
  assert.deepEqual(installedPackage("typescript", join(root, "package.json"))?.version, "7.0.2", "the project's TypeScript is found through its exports");
  const tsserver = locateTsserver(root, coherenceFrom);
  assert.deepEqual(tsserver, { path: join(store, "typescript", "lib", "tsserver.js"), version: "5.9.3", whose: "coherence", passedOver: "7.0.2" });
  assert.match(tsserverNotice(root, coherenceFrom), /^TypeScript: this project's TypeScript 7\.0\.2 ships no tsserver, so Coherence is using its own TypeScript 5\.9\.3 for readings/);
  const server = locateServer("typescript-language-server", "typescript-language-server", root, coherenceFrom, "");
  assert.ok(server.found, server.looked.join("\n"));
  assert.equal(server.path, join(store, "typescript-language-server", "lib", "cli.mjs"));
  assert.deepEqual([server.command, server.args], [process.execPath, [server.path]], "a package's bin script runs under this Node, whatever its mode bits");
  assert.match(server.looked[0]!, /^typescript-language-server resolved from the project \(.*\): not installed$/);
  assert.match(server.looked[1]!, /^typescript-language-server 5\.3\.0 resolved from Coherence/);
  const pyright = locateServer("pyright", "pyright-langserver", root, coherenceFrom, "");
  assert.ok(pyright.found && pyright.path === join(store, "pyright", "langserver.index.js"), pyright.looked.join("\n"));
});

test("the project's own tsserver and language server come first when it has them; a TypeScript whose tsserver.js is missing is passed over", () => {
  const { root, coherenceFrom } = pnpmProject("own-ts5");
  pkg(join(root, "node_modules", "typescript"), TS5("5.8.2"), ["lib/tsserver.js"]);
  pkg(join(root, "node_modules", "typescript-language-server"), { ...TSLS, version: "5.1.0" }, ["lib/cli.mjs"]);
  assert.deepEqual(locateTsserver(root, coherenceFrom), { path: join(root, "node_modules", "typescript", "lib", "tsserver.js"), version: "5.8.2", whose: "project", passedOver: undefined });
  assert.equal(tsserverNotice(root, coherenceFrom), "", "nothing to say when the project's own tsserver is driven");
  const server = locateServer("typescript-language-server", "typescript-language-server", root, coherenceFrom, "");
  assert.ok(server.found && server.path === join(root, "node_modules", "typescript-language-server", "lib", "cli.mjs"), server.looked.join("\n"));
  assert.equal(server.looked.length, 1, "the project's own is taken before Coherence's is looked for");
  // A typescript below 7 without its tsserver.js (a stub, a partial install) is no tsserver.
  rmSync(join(root, "node_modules", "typescript", "lib", "tsserver.js"));
  assert.equal(locateTsserver(root, coherenceFrom)?.whose, "coherence");
});

test("a server neither the project nor Coherence holds is found on PATH, and its absence names every place looked", () => {
  const root = join(scratch, "bare");
  write(join(root, "package.json"), "{}");
  const coherenceFrom = join(scratch, "bare-coherence", "dist", "adapters", "installed.js");
  write(coherenceFrom, "");
  const bin = join(scratch, "bare-bin");
  write(join(bin, "pyright-langserver"), "#!/bin/sh\n");
  const onPath = locateServer("pyright", "pyright-langserver", root, coherenceFrom, ["", join(scratch, "nowhere"), bin].join(":"));
  assert.ok(onPath.found && onPath.command === join(bin, "pyright-langserver") && onPath.args.length === 0, onPath.looked.join("\n"));
  const absent = locateServer("pyright", "pyright-langserver", root, coherenceFrom, join(scratch, "nowhere"));
  assert.equal(absent.found, false);
  assert.deepEqual(absent.looked.map((l) => l.replace(/ \(.*\)/, "")), ["pyright resolved from the project: not installed", "pyright resolved from Coherence: not installed", "pyright-langserver on PATH: none"]);
  assert.equal(locateTsserver(root, coherenceFrom), undefined);
});

test("orient says once that Coherence reads with its own TypeScript when the project's is 7 or later", async () => {
  const root = join(scratch, "orient-ts7");
  pkg(join(root, "node_modules", "typescript"), TS7, TS7_FILES);
  write(join(root, "package.json"), JSON.stringify({ name: "orient-ts7" }));
  write(join(root, "coherence.config.json"), JSON.stringify({ name: "orient-ts7", language: "typescript" }));
  const own = (JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), "..", "..", "node_modules", "typescript", "package.json"), "utf8")) as { version: string }).version;
  const line = `TypeScript: this project's TypeScript 7.0.2 ships no tsserver, so Coherence is using its own TypeScript ${own} for readings`;
  assert.ok(tsserverBlock(root).startsWith(line), tsserverBlock(root));
  const text = await startContext(root, { session_id: "orient-ts7" });
  assert.equal(text.split(line).length - 1, 1, `orient carries the line exactly once:\n${text.slice(0, 600)}`);
  write(join(root, "coherence.config.json"), JSON.stringify({ name: "orient-ts7", language: "python" }));
  assert.equal(tsserverBlock(root), "", "a project that reads no TypeScript is told nothing about its TypeScript");
});

/** Every non-test TypeScript source under a folder. */
function sources(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return sources(path);
    return /\.ts$/.test(name) && !/\.(test|e2e)\.ts$/.test(name) ? [path] : [];
  });
}

/** A path into node_modules built by hand: a join or resolve given the folder name, or a string spelling a path inside it. */
const HAND_BUILT = [/\b(?:join|resolve)\([^()]*["'`]node_modules["'`]/, /["'`][^"'`\n]*node_modules[\\/][\w@.$]/];

/**
 * The files allowed to spell one, and why: the hook command install writes is
 * shell the agent host runs before any Node is started, so no resolver can be
 * asked, and it looks for Coherence itself where every package manager links
 * a direct dependency (pnpm included); hook-command reads that shell back.
 */
const SHELL_ONLY = new Map([
  ["lifecycle/install.ts", "the committed hook command is shell, run before any Node resolver exists"],
  ["lifecycle/hook-command.ts", "it reads that shell back, to tell a hook an earlier Coherence wrote, and opens no path"],
]);

test("no source file builds a path into node_modules by hand: every package Coherence starts, drives or detects is found by the resolver", () => {
  const src = dirname(dirname(fileURLToPath(import.meta.url)));
  const found = sources(src)
    .filter((file) => !SHELL_ONLY.has(file.slice(src.length + 1)))
    .flatMap((file) =>
      readFileSync(file, "utf8")
        .split("\n")
        .flatMap((line, i) => (HAND_BUILT.some((pattern) => pattern.test(line)) ? [`${file.slice(src.length + 1)}:${i + 1}: ${line.trim()}`] : [])),
    );
  assert.deepEqual(found, [], "a hand-built node_modules path names nothing under pnpm, where a package's dependencies sit beside it, or past a package's exports; ask installed.ts");
  // The scan itself sees the shapes it refuses.
  for (const shape of [`join(root, "node_modules", ".bin", SERVER_BIN)`, "const p = `${root}/node_modules/typescript/lib/tsserver.js`;", `resolve(base, 'node_modules', "typescript")`]) {
    assert.ok(HAND_BUILT.some((pattern) => pattern.test(shape)), shape);
  }
});

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { existsSync, realpathSync } from "node:fs";
import { mkdtemp, mkdir, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { after, before, test } from "node:test";
import { fileURLToPath } from "node:url";
import { cliName, HOOK_EVENTS, REFUSE_EXIT } from "./hook.ts";
import { budget } from "../enforcement/test-budgets.ts";
import { PACKAGE_NAME } from "./project.ts";
import { CLAUDE_WRITER_MATCHER } from "./host-tools.ts";
import { modInstalled, ownModLinked } from "./mod-install.ts";
import { cli as inProcess } from "./cli-fixture.ts";
import { driftOf, EARLIER_SEARCH, earlierHookLines, formatCheck, formatStatus, formatUninstall, IGNORE_TEXT, install, LOCATED_PREFIX, searchesCheckoutFirst, locate, MISSING_CONTEXT, mergeHooks, NO_NODE, NOT_INSTALLED, status, stripHooks, uninstall } from "./install.ts";

const CLI = resolve(dirname(fileURLToPath(import.meta.url)), "..", "cli.ts");

let root: string;

// Node 22 runs the after hook without waiting for an async before when a name filter selects none of this file's tests, so the after waits for it.
let setup: Promise<void> | undefined;

before(() => (setup = (async () => {
  root = await mkdtemp(join(tmpdir(), "coherence-install-"));
  await mkdir(join(root, ".claude"));
  await writeFile(
    join(root, ".claude", "settings.json"),
    JSON.stringify(
      {
        permissions: { allow: ["Bash(npm test)"] },
        hooks: {
          Stop: [{ hooks: [{ type: "command", command: "./other-tool stop" }] }],
          PreToolUse: [{ matcher: "Bash", hooks: [{ type: "command", command: "./lint" }] }],
        },
      },
      null,
      2,
    ),
  );
})()));

after(async () => {
  await setup?.catch(() => undefined);
  if (root !== undefined) await rm(root, { recursive: true, force: true });
});

test("mergeHooks adds one Coherence entry per event, keeps everything else, and replaces its own entry on a second pass", () => {
  const first = mergeHooks({ hooks: { Stop: [{ hooks: [{ type: "command", command: "./other" }] }] }, other: 1 }, { command: "npx coherence", host: "claude" });
  const hooks = first["hooks"] as Record<string, { hooks: { command: string }[] }[]>;
  assert.equal(first["other"], 1);
  assert.deepEqual(hooks["Stop"]!.map((e) => e.hooks[0]!.command), ["./other", "npx coherence hook Stop"]);
  assert.deepEqual(hooks["SessionStart"]!.map((e) => e.hooks[0]!.command), ["npx coherence hook SessionStart"]);
  for (const event of HOOK_EVENTS) assert.ok(hooks[event]!.some((e) => e.hooks[0]!.command === `npx coherence hook ${event}`));

  const second = mergeHooks(first, { command: "node src/cli.ts", host: "claude" });
  const again = second["hooks"] as Record<string, { hooks: { command: string }[] }[]>;
  assert.deepEqual(again["Stop"]!.map((e) => e.hooks[0]!.command), ["./other", "node src/cli.ts hook Stop"]);
  assert.equal(again["SessionStart"]!.length, 1);

  // Only a command that names this tool's binary or its own cli path is Coherence's; a stranger's cli.ts that also takes "hook Stop" is kept.
  const foreign = [
    "node tools/other-project/cli.ts hook Stop",
    "./scripts/cli.ts hook Stop",
    "npx incoherence hook Stop",
    "my-coherence-wrapper hook Stop",
    'exec node "$incoherence" hook Stop',
  ];
  const crowded = mergeHooks({ hooks: { Stop: foreign.map((command) => ({ hooks: [{ type: "command", command }] })) } }, { command: "npx coherence", host: "claude" });
  const stop = (crowded["hooks"] as Record<string, { hooks: { command: string }[] }[]>)["Stop"]!;
  assert.deepEqual(stop.map((e) => e.hooks[0]!.command), [...foreign, "npx coherence hook Stop"], "no foreign hook is deleted");
  for (const command of ["npx coherence hook Stop", '"${CLAUDE_PROJECT_DIR:-.}/node_modules/.bin/coherence" hook Stop', "node src/cli.ts hook Stop", 'node "${CLAUDE_PROJECT_DIR:-.}/src/cli.ts" hook Stop', "coherence hook Stop", `${LOCATED_PREFIX} hook Stop`]) {
    const merged = mergeHooks({ hooks: { Stop: [{ hooks: [{ type: "command", command }] }] } }, { command: "npx coherence", host: "claude" });
    assert.deepEqual((merged["hooks"] as Record<string, { hooks: { command: string }[] }[]>)["Stop"]!.map((e) => e.hooks[0]!.command), ["npx coherence hook Stop"], `${command} is ours and is replaced`);
  }

  // An entry that carries a foreign hook beside ours keeps the foreign hook; only our command leaves it.
  const mixed = mergeHooks({ hooks: { Stop: [{ matcher: "x", hooks: [{ type: "command", command: "./theirs" }, { type: "command", command: "npx coherence hook Stop" }] }] } }, { command: "npx coherence", host: "claude" });
  const mixedStop = (mixed["hooks"] as Record<string, { matcher?: string; hooks: { command: string }[] }[]>)["Stop"]!;
  assert.deepEqual(mixedStop.map((e) => e.hooks.map((h) => h.command)), [["./theirs"], ["npx coherence hook Stop"]], "the foreign hook survives in its own entry, with its matcher");
  assert.equal(mixedStop[0]!.matcher, "x");
});

