/**
 * Where an installed package is, asked of Node's package resolver and never
 * spelled as a path: the language servers both adapters start and the
 * tsserver the TypeScript one drives. Under pnpm, Coherence's own
 * dependencies sit beside its package in the store, not inside it, so a path
 * built as <Coherence>/node_modules/<package> names nothing; the resolver,
 * asked from a file of Coherence's own, finds them wherever the package
 * manager put them. A package's exports map can refuse a subpath (TypeScript
 * 7 exports no lib/tsserver.js), so a package's folder is found by its
 * manifest, through the folders the resolver's own lookup walks, and a file
 * inside it is read from there.
 *
 * This module is the one place an adapter learns where a package is
 * (Adapters.spec.md, "packages found by the resolver"), and where the Rust
 * adapter learns where rust-analyzer is: a binary found on the machine, not
 * a package.
 */

import { existsSync, readFileSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { delimiter, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "../lifecycle/work-meter.ts";

/** A file of Coherence's own, which the resolver walks up from to find Coherence's dependencies. */
export const COHERENCE_FROM = fileURLToPath(import.meta.url);

export interface InstalledPackage {
  /** The package's folder. */
  dir: string;
  version: string;
  manifest: Record<string, unknown>;
}

/** The file the resolver starts from for a project: one at its root, which need not exist. */
export function projectFrom(root: string): string {
  return join(root, "package.json");
}

/**
 * A package as Node's resolver finds it from a file: its manifest resolved,
 * or, when the package's exports refuse that subpath, the first folder of the
 * resolver's lookup that holds it.
 */
export function installedPackage(name: string, from: string): InstalledPackage | undefined {
  const require = createRequire(from);
  const candidates: string[] = [];
  try {
    candidates.push(require.resolve(`${name}/package.json`));
  } catch {
    // not installed, or its exports refuse the manifest: the lookup folders below
  }
  for (const folder of require.resolve.paths(name) ?? []) candidates.push(join(folder, name, "package.json"));
  for (const manifestPath of candidates) {
    if (!existsSync(manifestPath)) continue;
    try {
      const manifest = JSON.parse(readFileSync(manifestPath, "utf8")) as Record<string, unknown>;
      if (manifest["name"] !== name) continue;
      return { dir: dirname(manifestPath), version: typeof manifest["version"] === "string" ? manifest["version"] : "unknown", manifest };
    } catch {
      continue;
    }
  }
  return undefined;
}

/** A regular file inside a package, or undefined when the package does not hold it. */
export function packageFile(found: InstalledPackage, file: string): string | undefined {
  const path = join(found.dir, file);
  try {
    return statSync(path).isFile() ? path : undefined;
  } catch {
    return undefined;
  }
}

/** The script a package's manifest names for a bin, when the package holds it. */
function binScript(found: InstalledPackage, bin: string): string | undefined {
  const bins = found.manifest["bin"];
  const named = typeof bins === "string" ? (found.manifest["name"] === bin ? bins : undefined) : bins !== null && typeof bins === "object" ? (bins as Record<string, unknown>)[bin] : undefined;
  return typeof named === "string" ? packageFile(found, named) : undefined;
}

/** How to start a language server: a package's script run by this Node, or a binary on PATH, with every place looked. */
export type ServerLocation = { found: true; command: string; args: string[]; path: string; looked: string[] } | { found: false; looked: string[] };

/**
 * A language server's binary: the package resolved from the project, then
 * from Coherence's own module, then the bin on PATH, in that order; absent,
 * the places looked, each named.
 */
export function locateServer(pkg: string, bin: string, root: string, coherenceFrom: string = COHERENCE_FROM, path: string = process.env["PATH"] ?? ""): ServerLocation {
  const looked: string[] = [];
  for (const [whose, from] of [["the project", projectFrom(root)], ["Coherence", coherenceFrom]] as const) {
    const found = installedPackage(pkg, from);
    const script = found === undefined ? undefined : binScript(found, bin);
    looked.push(found === undefined ? `${pkg} resolved from ${whose} (${dirname(from)}): not installed` : `${pkg} ${found.version} resolved from ${whose} (${found.dir})${script === undefined ? `: no ${bin} bin` : ""}`);
    if (script !== undefined) return { found: true, command: process.execPath, args: [script], path: script, looked };
  }
  for (const dir of path.split(delimiter)) {
    if (dir === "") continue;
    const candidate = join(dir, bin);
    if (existsSync(candidate)) return { found: true, command: candidate, args: [], path: candidate, looked: [...looked, `${bin} on PATH (${candidate})`] };
  }
  looked.push(`${bin} on PATH: none`);
  return { found: false, looked };
}

/** The first line a failed program printed, for a looked string. */
function firstLine(run: { stderr?: string | null; stdout?: string | null; error?: Error | undefined; status: number | null }): string {
  if (run.error !== undefined) return run.error.message;
  return `${run.stderr ?? ""}${run.stdout ?? ""}`.trim().split("\n")[0] || `exit ${run.status}`;
}

/**
 * rust-analyzer's binary, which is no npm package and so is found on the
 * machine, the way tach is: COHERENCE_RUST_ANALYZER when it names a file;
 * else `rustup which rust-analyzer` run from the project root, so its
 * rust-toolchain.toml is honoured; else the first rust-analyzer on PATH that
 * answers `--version`, since rustup's proxy at ~/.cargo/bin exists without
 * the component and fails only when run. Absent, every place looked is named.
 */
export function locateRustAnalyzer(root: string, bin = "rust-analyzer", env: NodeJS.ProcessEnv = process.env): ServerLocation {
  const looked: string[] = [];
  const explicit = env["COHERENCE_RUST_ANALYZER"];
  if (explicit !== undefined && explicit !== "") {
    if (existsSync(explicit)) return { found: true, command: explicit, args: [], path: explicit, looked: [...looked, `COHERENCE_RUST_ANALYZER (${explicit})`] };
    looked.push(`COHERENCE_RUST_ANALYZER (${explicit}): no such file`);
  } else looked.push("COHERENCE_RUST_ANALYZER: unset");
  const dirs = (env["PATH"] ?? "").split(delimiter).filter((dir) => dir !== "");
  const childEnv = { ...process.env, ...env };
  const rustup = dirs.map((dir) => join(dir, "rustup")).find((candidate) => existsSync(candidate));
  if (rustup === undefined) looked.push(`rustup which ${bin}: no rustup on PATH`);
  else {
    const which = spawnSync(rustup, ["which", bin], { cwd: root, encoding: "utf8", env: childEnv, timeout: 30_000 });
    const path = which.status === 0 ? which.stdout.trim() : "";
    if (path !== "" && existsSync(path)) return { found: true, command: path, args: [], path, looked: [...looked, `rustup which ${bin} (${path})`] };
    looked.push(`rustup which ${bin}: ${firstLine(which)}`);
  }
  let onPath = false;
  for (const dir of dirs) {
    const candidate = join(dir, bin);
    if (!existsSync(candidate)) continue;
    onPath = true;
    const probe = spawnSync(candidate, ["--version"], { cwd: root, encoding: "utf8", env: childEnv, timeout: 30_000 });
    if (probe.status === 0) return { found: true, command: candidate, args: [], path: candidate, looked: [...looked, `${bin} on PATH (${candidate})`] };
    const said = firstLine(probe);
    looked.push(`${bin} on PATH (${candidate}): ${/unknown binary/i.test(said) ? `a rustup proxy without the ${bin} component (${said})` : said}`);
  }
  if (!onPath) looked.push(`${bin} on PATH: none`);
  return { found: false, looked };
}

/** The first number of a version. */
function major(version: string): number {
  return Number.parseInt(version, 10);
}

/** The tsserver the TypeScript language server drives, whose it is, and, when it is Coherence's, the project's TypeScript it stands in for. */
export interface TsserverChoice {
  path: string;
  version: string;
  whose: "project" | "coherence";
  /** The project's own TypeScript when it is installed but ships no tsserver (TypeScript 7 and later). */
  passedOver: string | undefined;
}

/**
 * The tsserver to drive: the project's own typescript/lib/tsserver.js when
 * that file exists and is a tsserver (TypeScript below 7: from 7 the language
 * service is native and ships none), otherwise Coherence's own, resolved from
 * its module; undefined when neither holds one.
 */
export function locateTsserver(root: string, coherenceFrom: string = COHERENCE_FROM): TsserverChoice | undefined {
  const project = installedPackage("typescript", projectFrom(root));
  const own = project === undefined ? undefined : packageFile(project, "lib/tsserver.js");
  if (project !== undefined && own !== undefined && major(project.version) < 7) return { path: own, version: project.version, whose: "project", passedOver: undefined };
  const passedOver = project === undefined ? undefined : project.version;
  const coherence = installedPackage("typescript", coherenceFrom);
  const theirs = coherence === undefined ? undefined : packageFile(coherence, "lib/tsserver.js");
  if (coherence !== undefined && theirs !== undefined && major(coherence.version) < 7) return { path: theirs, version: coherence.version, whose: "coherence", passedOver };
  return undefined;
}

/**
 * The line an agent reads when the project's TypeScript ships no tsserver and
 * Coherence reads with its own; empty otherwise.
 */
export function tsserverNotice(root: string, coherenceFrom: string = COHERENCE_FROM): string {
  const project = installedPackage("typescript", projectFrom(root));
  if (project === undefined || major(project.version) < 7) return "";
  const choice = locateTsserver(root, coherenceFrom);
  if (choice === undefined) return `TypeScript: this project's TypeScript ${project.version} ships no tsserver and Coherence has no TypeScript of its own installed, so no TypeScript reading can be made; install Coherence with its optional dependencies (its typescript is one).`;
  return `TypeScript: this project's TypeScript ${project.version} ships no tsserver, so Coherence is using its own TypeScript ${choice.version} for readings (references, symbols and the compiler's refusals).`;
}

/**
 * Coherence's Claude Code mod, enabled for one person in one project.
 *
 * The mod (mods/coherence) answers Claude Code's hook events through one warm
 * process per session instead of a settings hook per event. Coherence's
 * repository is its marketplace (.claude-plugin/marketplace.json, one entry,
 * the mod's folder), and the mod runs the project's own installed Coherence,
 * so it is a forwarder that any project's version can sit behind: an event
 * the warm process cannot answer runs through `coherence hook` as a settings
 * hook would.
 *
 * Install is Claude Code's own: `claude plugin marketplace add
 * PostHog/coherence --scope local` and `claude plugin install
 * coherence@coherence --scope local`, which write the project's personal
 * settings (.claude/settings.local.json, never committed). The marketplace is
 * the repository, never a project's node_modules folder: Claude Code knows a
 * marketplace by its name on the whole machine, so a second project
 * registering its own folder would repoint the first project's mod at it.
 * Enabling is personal because the fast path is opt-in: teammates keep the
 * committed settings hooks until they choose the mod.
 *
 * The mod stands aside for every event whose settings hooks already run
 * Coherence, so install removes Coherence's hooks from the personal settings
 * and leaves the committed ones, which belong to the team, and says while
 * they remain that the mod answers no event they cover.
 */

import { readFileSync, realpathSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { spawnSync } from "./work-meter.ts";
import { LOCAL_SETTINGS_FILE, SETTINGS_FILE } from "./project.ts";
import { HOST_FOLDER } from "./hosts.ts";

export const MOD_NAME = "coherence";
export const MOD_MARKETPLACE = "coherence";
export const MOD_ID = `${MOD_NAME}@${MOD_MARKETPLACE}`;
/** The marketplace: Coherence's repository, as `claude plugin marketplace add` takes it. */
export const MOD_REPOSITORY = "PostHog/coherence";
/** Where the mod sits in the repository, and the marketplace file that lists it, both relative to its root. */
export const MOD_FOLDER = join("mods", MOD_NAME);
export const MARKETPLACE_FILE = join(".claude-plugin", "marketplace.json");

/** Runs `claude` with these arguments; injected so tests run none. */
export type ClaudeRunner = (args: readonly string[], cwd: string) => { status: number | null; stdout: string; stderr: string };

export const runClaude: ClaudeRunner = (args, cwd) => {
  const ran = spawnSync("claude", [...args], { cwd, encoding: "utf8" });
  return { status: ran.error === undefined ? ran.status : null, stdout: ran.stdout ?? "", stderr: ran.error === undefined ? (ran.stderr ?? "") : ran.error.message };
};

/**
 * The personal settings file Claude Code's local scope writes for a folder:
 * the main checkout's, also for a folder in one of its git worktrees, since
 * Claude Code knows a project by its repository. So enabling the mod in a
 * worktree enables it in the main checkout and every worktree of it.
 */
export function localSettingsPath(root: string): string {
  const common = spawnSync("git", ["-C", root, "rev-parse", "--path-format=absolute", "--git-common-dir"], { encoding: "utf8" });
  const dir = common.status === 0 ? common.stdout.trim() : "";
  return join(basename(dir) === ".git" ? dirname(dir) : root, LOCAL_SETTINGS_FILE.claude!);
}

/**
 * Where the mod is enabled: `local` is one person's (Claude Code's local
 * scope), `project` the team's, in the committed settings, which Claude Code
 * keeps in the folder itself, a worktree's own included.
 */
export type ModScope = "local" | "project";

/** The settings file a scope keeps the mod's enabling and its marketplace's declaration in. */
export function modSettingsPath(root: string, scope: ModScope): string {
  return scope === "local" ? localSettingsPath(root) : join(root, SETTINGS_FILE.claude);
}

/** Whether the settings Claude Code reads for this folder at this scope enable the mod. */
export function modInstalled(root: string, scope: ModScope = "local"): boolean {
  try {
    const settings = JSON.parse(readFileSync(modSettingsPath(root, scope), "utf8")) as { enabledPlugins?: Record<string, unknown> };
    return settings.enabledPlugins?.[MOD_ID] === true;
  } catch {
    return false;
  }
}

export interface ModStep {
  args: string[];
  ok: boolean;
  said: string;
}

/** What a `claude plugin` call said: its last JSON line's message, else its output. */
function said(out: { stdout: string; stderr: string }): string {
  const last = out.stdout.trim().split("\n").at(-1) ?? "";
  try {
    const message = (JSON.parse(last) as { message?: unknown }).message;
    if (typeof message === "string") return message.trim().split("\n").at(-1) ?? "";
  } catch {
    // Not JSON: the text itself.
  }
  return (out.stderr.trim() || out.stdout.trim()).split("\n").at(-1) ?? "";
}

function step(run: ClaudeRunner, root: string, args: string[]): ModStep {
  const out = run(args, root);
  return { args, ok: out.status === 0, said: out.status === null ? `claude could not be run (${out.stderr || "not on the PATH"})` : said(out) };
}

/** Register Coherence's repository as a marketplace and install the mod, both at one scope; stops at the first step that fails. */
export function installMod(root: string, run: ClaudeRunner = runClaude, scope: ModScope = "local"): ModStep[] {
  const steps = [step(run, root, ["plugin", "marketplace", "add", MOD_REPOSITORY, "--scope", scope, "--json"])];
  if (steps[0]!.ok) steps.push(step(run, root, ["plugin", "install", MOD_ID, "--scope", scope, "--json"]));
  return steps;
}

/**
 * Uninstall the mod from the personal scope, then drop the marketplace's
 * declaration that install wrote there, by editing the file: `claude plugin
 * marketplace remove` would uninstall the mod from every project on the
 * machine, since Claude Code knows the marketplace machine-wide.
 */
export function uninstallMod(root: string, run: ClaudeRunner = runClaude, scope: ModScope = "local"): ModStep[] {
  const steps = [step(run, root, ["plugin", "uninstall", MOD_ID, "--scope", scope, "--json"])];
  if (steps[0]!.ok && dropDeclaration(modSettingsPath(root, scope))) steps.push({ args: ["marketplace declaration", MOD_MARKETPLACE], ok: true, said: `removed from ${modSettingsPath(root, scope)}; other projects keep the marketplace` });
  return steps;
}

/** Remove a settings file's declaration of Coherence's marketplace, only when it names Coherence's repository; keeps the file's indentation. */
function dropDeclaration(path: string): boolean {
  let text: string;
  let settings: { extraKnownMarketplaces?: Record<string, { source?: { source?: unknown; repo?: unknown } }> };
  try {
    text = readFileSync(path, "utf8");
    settings = JSON.parse(text) as typeof settings;
  } catch {
    return false;
  }
  const declared = settings.extraKnownMarketplaces?.[MOD_MARKETPLACE]?.source;
  if (declared?.source !== "github" || declared.repo !== MOD_REPOSITORY) return false;
  delete settings.extraKnownMarketplaces![MOD_MARKETPLACE];
  if (Object.keys(settings.extraKnownMarketplaces!).length === 0) delete settings.extraKnownMarketplaces;
  const indent = /^[ \t]+/m.exec(text)?.[0] ?? "  ";
  writeFileSync(path, JSON.stringify(settings, null, indent) + (text.endsWith("\n") ? "\n" : ""));
  return true;
}

/**
 * Where Coherence's own repository keeps its mod for Claude Code: a link in
 * the project's skills folder to the tree's own mods/coherence. Claude Code
 * loads a plugin from there in every session in the folder and reloads it
 * when a file of it is saved, so the main checkout and each worktree run
 * their own mod, edits included. An installed copy of the mod for this
 * repository or for the user takes the name first and the link is not
 * loaded, so the repository never installs one.
 */
export const OWN_MOD_LINK = join(HOST_FOLDER.claude, "skills", MOD_NAME);

/** Whether the skills-folder link resolves to this tree's own mod. */
export function ownModLinked(root: string): boolean {
  try {
    return realpathSync(join(root, OWN_MOD_LINK)) === realpathSync(join(root, MOD_FOLDER));
  } catch {
    return false;
  }
}

// usage: node measure-model.ts <coherence checkout> <project root>, after `query structure` recorded a reading.
// The spec model, the gaps against the recorded reading, the baselines and the control lines, as JSON.
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
const [C, root] = process.argv.slice(2);
const gapsMod = await import(join(C!, "src/readings/scope/gaps.ts"));
const modelMod = await import(join(C!, "src/spec/model.ts"));
const journal = await import(join(C!, "src/journal/store.ts"));
const model = modelMod.loadSpecModel(root, {});
const trusted = new Set(model.trustLevels.filter((l: any) => !l.outside).map((l: any) => l.name));
const ents = model.components.flatMap((c: any) => c.entrances);
const g = gapsMod.currentGaps(root);
let baselines: any[] = [];
const { records } = journal.loadJournal(root);
for (const r of records) if (r.kind === "decision" && /^structure baseline /.test(r.chose)) {
  let n = -1; try { n = JSON.parse(r.chose.replace(/^structure baseline /, "")).gaps.length; } catch {}
  baselines.push({ id: r.id, size: n });
}
let effective: any; try { effective = gapsMod.readGapBaseline(root); } catch (e) { effective = { error: String(e) }; }
const specFiles: string[] = model.components.map((c: any) => join(root!, c.specPath));
let guardLines = 0, trustLines = 0, controlLines = 0;
for (const f of specFiles) { if (!existsSync(f)) continue; for (const l of readFileSync(f, "utf8").split("\n")) { if (/^\s*guard:/.test(l)) guardLines++; if (/^\s*trust:/.test(l)) trustLines++; if (/^\s*control:/.test(l)) controlLines++; } }
console.log(JSON.stringify({
  components: model.components.length,
  trustLevels: model.trustLevels.map((l: any) => ({ name: l.name, outside: !!l.outside })),
  entrances: ents.length,
  entrancesWithTrust: ents.filter((e: any) => e.trust !== undefined).length,
  entrancesUntrustedOrUnknown: ents.filter((e: any) => e.trust === undefined || !trusted.has(e.trust)).length,
  entrancesWithGuard: ents.filter((e: any) => e.guard !== undefined).length,
  waivers: ents.filter((e: any) => e.noControl !== undefined).map((e: any) => ({ component: e.component, name: e.name, reason: e.noControl })),
  guardLines, trustLines, controlLines,
  counts: model.counts,
  specProblems: model.problems.length,
  gaps: g === undefined ? null : g.gaps.map((x: any) => [x.component, x.name, x.trust.join("|")]),
  gapReadingAt: g?.at ?? null,
  baselines,
  effectiveBaseline: effective === undefined ? null : (effective.error ?? effective.entrances.size),
  journalRecords: records.length,
}));

/**
 * The mirror reading's model: what a reading holds, as plain data a record
 * can keep and orient can read without loading the reading itself.
 */

export type Form =
  | "array" | "set" | "keys" | "values" | "column" | "alternation" | "union" | "cases"
  | "doc-alternation" | "doc-table" | "prose"
  | "folder" | "closure" | "exports" | "reads";

export const DOC_FORMS: ReadonlySet<Form> = new Set<Form>(["doc-alternation", "doc-table", "prose"]);
/** Sets code derives: never kept by hand, so a finding needs a literal on its other side. */
export const DERIVED: ReadonlySet<Form> = new Set<Form>(["folder", "closure", "exports", "reads"]);

export type Verdict = "drifted" | "latent" | "duplicate";

/** One set as a finding names it: where it is, what it is, and what it holds. */
export interface SetRef {
  file: string;
  /** 0 for a universe, which has no line of its own. */
  line: number;
  name: string;
  form: Form;
  /** The compiler holds these to a type (`Record<Kind, …>`, an exhaustive switch): not kept by hand. */
  checked: boolean;
  members: string[];
  /** For an import closure: the files whose imports it follows, as the list spells them. */
  of?: string[];
  /** For the import closure of a list of files: where that list is, as file:line. */
  list?: string;
}

export interface Missed {
  /** The commit, abbreviated to seven characters. */
  commit: string;
  subject: string;
  member: string;
  /** Which side the commit grew alone. */
  side: "a" | "b";
}

export interface MirrorHistory {
  /** Commits that grew both sides by the same name, the birth of neither. */
  together: string[];
  /** Shared names added to each side in different commits. */
  lagged: string[];
  /** Commits that grew one side by a name now only on that side. */
  missed: Missed[];
}

export interface Finding {
  /** The hand-kept side. */
  a: SetRef;
  b: SetRef;
  verdict: Verdict;
  shared: string[];
  onlyA: string[];
  onlyB: string[];
  /** A third set that accounts for the difference: A is B together with it. */
  union?: SetRef;
  jaccard: number;
  containment: number;
  score: number;
  overlapScore: number;
  historyScore: number;
  /** The other sets equal to one side: the copies this finding stands for. */
  copies: SetRef[];
  history?: MirrorHistory;
}

/** Findings that share a cluster: one question for the reader, ranked by its strongest finding. */
export interface Group {
  rank: number;
  score: number;
  overlapScore: number;
  historyScore: number;
  findings: Finding[];
}

export interface MirrorReading {
  /** The revision as asked for (HEAD by default). */
  rev: string;
  /** The commit it resolved to. */
  commit: string;
  /** Milliseconds the reading took, and per phase. */
  ms: number;
  phases: Record<string, number>;
  sets: number;
  /** The code files the reading parsed (TypeScript and JavaScript). */
  read: number;
  /** The tracked files in a language the reading does not parse, counted by extension: `{ ".py": 4123 }`. */
  unread: Record<string, number>;
  groups: Group[];
}
